#include "ksLegacySysExTask.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>
using T=ks::LegacySysExTask;using S=T::Stage;using C=T::Child;using K=T::Kind;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}int main(){try{uint64_t cases=0;for(unsigned kind=0;kind<4;++kind)for(unsigned bank=0;bank<256;++bank)for(unsigned program=0;program<256;++program){T t{K(kind)};std::array<uint8_t,256>payload{};std::array<uint8_t,128>backup{};for(unsigned i=0;i<256;++i)payload[i]=uint8_t(i+program);std::vector<C>children;unsigned record=0,expands=0;uint8_t published=uint8_t(program);unsigned mode=bank&1;auto read=[&](S s)->uint32_t{switch(s){case S::ApplyReadMode:return mode;case S::PatchReadBank:case S::MultiReadBank:return bank;case S::PatchReadProgram:case S::MultiReadProgram:case S::PairReadProgram:return program;case S::PairReadSource:return payload[128+t.index()];case S::PairReadBackup:return backup[t.index()];default:throw std::runtime_error("Unexpected legacy read");}};auto write=[&](S s,uint32_t v){if(s==S::PairPublishBackup)backup[t.index()]=uint8_t(v);else if(s==S::PairPublishSource)payload[t.index()]=uint8_t(v);else if(s==S::PairPublishProgram)published=uint8_t(v);else throw std::runtime_error("Unexpected legacy write");};unsigned guard=0;
while(!t.complete()&&!t.handoff()){check(++guard<2000,"Legacy pure stalled");if(t.awaitingChild()){auto c=t.child();children.push_back(c);if(c==C::Active)check(t.resumeActive(program&1),"Active reply");else if(c==C::Resolve){check(t.resumeResolve(0xffff1234u),"Resolve reply");record=0xffff1234u;}else {if(c==C::Expand&&kind==3){++expands;if(expands==1)payload.fill(0xee);else for(unsigned i=0;i<128;++i)check(payload[i]==uint8_t(128+i+program),"Second legacy half not restored before expansion");}check(t.resumeChild(),"Void reply");}continue;}const auto old=t.stage();const auto cost=t.nextClocks(3);check(cost!=0,"Missing legacy pure cost");check(t.advanceBefore(cost-1,read,write,[](S){return 3u;})==0&&old==t.stage(),"Early legacy deadline mutated");check(t.advanceBefore(cost,read,write,[](S){return 3u;})==cost,"Legacy exact deadline");}
std::vector<C>expected;if(kind==0){if(!mode){expected={C::Expand,C::ApplyPatch,C::Active};if(program&1)expected.push_back(C::Refresh);check(t.handoff()&&t.route()==T::Route::Notify,"Legacy notify route");}else check(t.complete(),"Legacy apply modeguard");}else if(kind==1){expected={C::Resolve};if(bank>=1&&bank<=4&&program<100){expected.push_back(C::Report);expected.push_back(C::Expand);expected.push_back(C::Commit);}check(t.complete(),"Legacy patchreturn");}else if(kind==2){expected={C::Resolve};if(bank>=1&&bank<=4&&!(program&1)&&program<=98){expected.push_back(C::Report);expected.push_back(C::WritePair);}check(t.complete(),"Legacy multireturn");}else{expected={C::Expand,C::Commit,C::Expand,C::Resolve};check(published==uint8_t(program+1),"Legacy programwrap");check(t.handoff()&&t.route()==T::Route::Commit,"Legacy paircommit route");check(record==0xffff1234u&&t.record()==record,"Legacy recordreply lost");for(unsigned i=0;i<128;++i)check(backup[i]==uint8_t(128+i+program),"Legacy backup order");}check(children==expected,"Legacy semantic child sequence");++cases;}
std::cout<<"PASS: "<<cases<<" pure legacy SysEx tasks; independent bank/program/parity/mode oracle, copy/restore/expand sequencing, unsigned program wrap, typed replies and early deadlines\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
